def cmd_setup(args) -> None:
    """Interactive memory provider setup wizard."""
    from hermes_cli.config import load_config, save_config
    providers = _get_available_providers()
    if not providers:
        print('\n  No memory provider plugins detected.')
        print('  Install a plugin to ~/.hermes/plugins/ and try again.\n')
        return
    items = []
    for name, desc, _ in providers:
        items.append((name, f'— {desc}'))
    items.append(('Built-in only', '— MEMORY.md / USER.md (default)'))
    builtin_idx = len(items) - 1
    selected = _curses_select('Memory provider setup', items, default=builtin_idx, cancel_returns=_CANCELLED)
    if selected == _CANCELLED:
        _print_cancelled_setup()
        return
    config = load_config()
    if not isinstance(config.get('memory'), dict):
        config['memory'] = {}
    if selected >= len(providers):
        config['memory']['provider'] = ''
        save_config(config)
        print('\n  ✓ Memory provider: built-in only')
        print('  Saved to config.yaml\n')
        return
    name, _, provider = providers[selected]
    _clear_interactive_transition()
    _install_dependencies(name)
    if hasattr(provider, 'post_setup'):
        hermes_home = str(get_hermes_home())
        provider.post_setup(hermes_home, config)
        return
    schema = provider.get_config_schema() if hasattr(provider, 'get_config_schema') else []
    provider_config = config['memory'].get(name, {})
    if not isinstance(provider_config, dict):
        provider_config = {}
    env_path = get_hermes_home() / '.env'
    env_writes = {}
    if schema:
        print(f'\n  Configuring {name}:\n')
        for field in schema:
            key = field['key']
            desc = field.get('description', key)
            default = field.get('default')
            default_from = field.get('default_from')
            if default_from and isinstance(default_from, dict):
                ref_field = default_from.get('field', '')
                ref_map = default_from.get('map', {})
                ref_value = provider_config.get(ref_field, '')
                if ref_value and ref_value in ref_map:
                    default = ref_map[ref_value]
            is_secret = field.get('secret', False)
            choices = field.get('choices')
            env_var = field.get('env_var')
            url = field.get('url')
            when = field.get('when')
            if when and isinstance(when, dict):
                if not all((provider_config.get(k) == v for k, v in when.items())):
                    continue
            if choices and (not is_secret):
                choice_items = [(c, '') for c in choices]
                current = provider_config.get(key, default)
                current_idx = 0
                if current and current in choices:
                    current_idx = choices.index(current)
                sel = _curses_select(f'  {desc}', choice_items, default=current_idx, cancel_returns=_CANCELLED)
                if sel == _CANCELLED:
                    _print_cancelled_setup()
                    return
                provider_config[key] = choices[sel]
            elif is_secret:
                existing = os.environ.get(env_var, '') if env_var else ''
                if existing:
                    masked = f'...{existing[-4:]}' if len(existing) > 4 else 'set'
                    val = _prompt(f'{desc} (current: {masked}, blank to keep)', secret=True)
                else:
                    hint = f'  Get yours at {url}' if url else ''
                    if hint:
                        print(hint)
                    val = _prompt(desc, secret=True)
                if val and env_var:
                    env_writes[env_var] = val
            else:
                current = provider_config.get(key)
                effective_default = current or default
                val = _prompt(desc, default=str(effective_default) if effective_default else None)
                if val:
                    provider_config[key] = val
                    if env_var and env_var not in env_writes:
                        env_writes[env_var] = val
    config['memory']['provider'] = name
    save_config(config)
    hermes_home = str(get_hermes_home())
    if provider_config and hasattr(provider, 'save_config'):
        try:
            provider.save_config(provider_config, hermes_home)
        except Exception as e:
            print(f'  Failed to write provider config: {e}')
    if env_writes:
        _write_env_vars(env_path, env_writes)
    print(f'\n  Memory provider: {name}')
    print(f'  Activation saved to config.yaml')
    if provider_config:
        print(f'  Provider config saved')
    if env_writes:
        print(f'  API keys saved to .env')
    print(f'\n  Start a new session to activate.\n')

