def _cleanup_inactive_browser_sessions():
    """
    Clean up browser sessions that have been inactive for longer than the timeout.

    This function is called periodically by the background cleanup thread to
    automatically close sessions that haven't been used recently, preventing
    orphaned sessions (local or Browserbase) from accumulating.
    """
    current_time = time.time()
    sessions_to_cleanup = []
    with _cleanup_lock:
        for task_id, last_time in list(_session_last_activity.items()):
            if current_time - last_time > BROWSER_SESSION_INACTIVITY_TIMEOUT:
                sessions_to_cleanup.append(task_id)
    for task_id in sessions_to_cleanup:
        try:
            elapsed = int(current_time - _session_last_activity.get(task_id, current_time))
            logger.info('Cleaning up inactive session for task: %s (inactive for %ss)', task_id, elapsed)
            cleanup_browser(task_id)
            with _cleanup_lock:
                if task_id in _session_last_activity:
                    del _session_last_activity[task_id]
        except Exception as e:
            logger.warning('Error cleaning up inactive session %s: %s', task_id, e)

def _stop_browser_cleanup_thread():
    """Stop the background cleanup thread."""
    global _cleanup_running
    _cleanup_running = False
    if _cleanup_thread is not None:
        _cleanup_thread.join(timeout=5)

def _maybe_stop_recording(task_id: str):
    """Stop recording if one is active for this session."""
    with _cleanup_lock:
        if task_id not in _recording_sessions:
            return
    try:
        result = _run_browser_command(task_id, 'record', ['stop'])
        if result.get('success'):
            path = result.get('data', {}).get('path', '')
            logger.info('Saved browser recording for session %s: %s', task_id, path)
    except Exception as e:
        logger.debug('Could not stop recording for %s: %s', task_id, e)
    finally:
        with _cleanup_lock:
            _recording_sessions.discard(task_id)

def _cleanup_old_screenshots(screenshots_dir, max_age_hours=24):
    """Remove browser screenshots older than max_age_hours to prevent disk bloat.

    Throttled to run at most once per hour per directory to avoid repeated
    scans on screenshot-heavy workflows.
    """
    key = str(screenshots_dir)
    now = time.time()
    if now - _last_screenshot_cleanup_by_dir.get(key, 0.0) < 3600:
        return
    _last_screenshot_cleanup_by_dir[key] = now
    try:
        cutoff = time.time() - max_age_hours * 3600
        for f in screenshots_dir.glob('browser_screenshot_*.png'):
            try:
                if f.stat().st_mtime < cutoff:
                    f.unlink()
            except Exception as e:
                logger.debug('Failed to clean old screenshot %s: %s', f, e)
    except Exception as e:
        logger.debug('Screenshot cleanup error (non-critical): %s', e)

def _cleanup_old_recordings(max_age_hours=72):
    """Remove browser recordings older than max_age_hours to prevent disk bloat."""
    try:
        hermes_home = get_hermes_home()
        recordings_dir = hermes_home / 'browser_recordings'
        if not recordings_dir.exists():
            return
        cutoff = time.time() - max_age_hours * 3600
        for f in recordings_dir.glob('session_*.webm'):
            try:
                if f.stat().st_mtime < cutoff:
                    f.unlink()
            except Exception as e:
                logger.debug('Failed to clean old recording %s: %s', f, e)
    except Exception as e:
        logger.debug('Recording cleanup error (non-critical): %s', e)

def _cleanup_single_browser_session(task_id: str) -> None:
    """Internal: reap a single browser session by its exact session key."""
    _stop_cdp_supervisor(task_id)
    if _is_camofox_mode():
        try:
            from tools.browser_camofox import camofox_close, camofox_soft_cleanup
            if not camofox_soft_cleanup(task_id):
                camofox_close(task_id)
        except Exception as e:
            logger.debug('Camofox cleanup for task %s: %s', task_id, e)
    logger.debug('cleanup_browser called for task_id: %s', task_id)
    logger.debug('Active sessions: %s', list(_active_sessions.keys()))
    with _cleanup_lock:
        session_info = _active_sessions.get(task_id)
    if session_info:
        bb_session_id = session_info.get('bb_session_id', 'unknown')
        logger.debug('Found session for task %s: bb_session_id=%s', task_id, bb_session_id)
        _maybe_stop_recording(task_id)
        try:
            _run_browser_command(task_id, 'close', [], timeout=10)
            logger.debug('agent-browser close command completed for task %s', task_id)
        except Exception as e:
            logger.warning('agent-browser close failed for task %s: %s', task_id, e)
        with _cleanup_lock:
            _active_sessions.pop(task_id, None)
            _session_last_activity.pop(task_id, None)
        if bb_session_id:
            provider = _get_cloud_provider()
            if provider is not None:
                try:
                    provider.close_session(bb_session_id)
                except Exception as e:
                    logger.warning('Could not close cloud browser session: %s', e)
        session_name = session_info.get('session_name', '')
        if session_name:
            socket_dir = os.path.join(_socket_safe_tmpdir(), f'agent-browser-{session_name}')
            if os.path.exists(socket_dir):
                pid_file = os.path.join(socket_dir, f'{session_name}.pid')
                if os.path.isfile(pid_file):
                    try:
                        from tools.process_registry import ProcessRegistry
                        daemon_pid = int(Path(pid_file).read_text(encoding='utf-8').strip())
                        ProcessRegistry._terminate_host_pid(daemon_pid)
                        logger.debug('Killed daemon pid %s for %s', daemon_pid, session_name)
                    except (ProcessLookupError, ValueError, PermissionError, OSError):
                        logger.debug('Could not kill daemon pid for %s (already dead or inaccessible)', session_name)
                shutil.rmtree(socket_dir, ignore_errors=True)
        logger.debug('Removed task %s from active sessions', task_id)
    else:
        logger.debug('No active session found for task_id: %s', task_id)

def _reinject_post_build_tools(agent, tools_list: list, name_set: set) -> set:
    """Append memory-provider and context-engine tools onto staged locals.

    Mirrors the post-``get_tool_definitions`` injection in ``agent_init`` so a
    snapshot rebuild reconstructs the FULL tool surface, not just the
    registry-derived subset. Operates ONLY on the caller's staged ``tools_list``
    / ``name_set`` (never the live agent attributes) so the rebuild stays atomic.
    Idempotent (skips names already present) and fail-soft.

    Returns the set of context-engine routing names actually appended by THIS
    rebuild — matching ``agent_init``'s dedup behavior (a name already provided
    by a registry/plugin tool is NOT claimed for context-engine routing). The
    caller publishes this into ``agent._context_engine_tool_names`` atomically
    with the snapshot.
    """

    def _add(schema: dict) -> bool:
        name = schema.get('name', '')
        if not name or name in name_set:
            return False
        tools_list.append({'type': 'function', 'function': schema})
        name_set.add(name)
        return True
    try:
        memory_manager = getattr(agent, '_memory_manager', None)
        get_mem_schemas = getattr(memory_manager, 'get_all_tool_schemas', None) if memory_manager else None
        if callable(get_mem_schemas):
            from agent.memory_manager import memory_provider_tools_enabled
            if 'memory' in name_set or memory_provider_tools_enabled(getattr(agent, 'enabled_toolsets', None)):
                for schema in get_mem_schemas():
                    if isinstance(schema, dict):
                        _add(schema)
    except Exception:
        logger.debug('Memory-provider tool re-injection skipped', exc_info=True)
    staged_engine_names: set = set()
    try:
        enabled = getattr(agent, 'enabled_toolsets', None)
        context_engine_allowed = enabled is None or 'context_engine' in enabled
        compressor = getattr(agent, 'context_compressor', None)
        get_schemas = getattr(compressor, 'get_tool_schemas', None) if compressor else None
        if context_engine_allowed and callable(get_schemas):
            for schema in get_schemas():
                if not isinstance(schema, dict):
                    continue
                name = schema.get('name', '')
                if _add(schema) and name:
                    staged_engine_names.add(name)
    except Exception:
        logger.debug('Context-engine tool re-injection skipped', exc_info=True)
    return staged_engine_names
